variables.script_transition:
{# Slow for background updates; quick for motion or a manual run. #} {% if trigger is defined and trigger.id is defined and trigger.id in ['phase_change', 'tick', 'extra', 'recovered'] %}
  {{ background_transition }}
{% else %}
  {{ motion_on_transition }}
{% endif %}

variables.target_ids:
{% set ns = namespace(entities=[], devices=[], areas=[]) %} {% for key in ['entity_id', 'device_id', 'area_id', 'floor_id', 'label_id'] %}
  {% set v = room_target.get(key, []) %}
  {% set ids = [v] if v is string else v %}
  {% if key == 'entity_id' %}{% set ns.entities = ns.entities + ids %}
  {% elif key == 'device_id' %}{% set ns.devices = ns.devices + ids %}
  {% elif key == 'area_id' %}{% set ns.areas = ns.areas + ids %}
  {% elif key == 'floor_id' %}
    {% for f in ids %}{% set ns.areas = ns.areas + floor_areas(f) %}{% endfor %}
  {% else %}
    {% for l in ids %}
      {% set ns.entities = ns.entities + label_entities(l) %}
      {% set ns.devices = ns.devices + label_devices(l) %}
      {% set ns.areas = ns.areas + label_areas(l) %}
    {% endfor %}
  {% endif %}
{% endfor %} {{ {'entities': ns.entities | unique | list, 'devices': ns.devices | unique | list, 'areas': ns.areas | unique | list} }}

variables.phase_exclude_lights:
{% set m = {'Morning': morning_exclude_lights, 'Day': day_exclude_lights,
            'Evening': evening_exclude_lights, 'Night': night_exclude_lights} %}
{{ m.get(phase, []) }}

variables.template_brightness_map:
{% set t = template_brightness_levels %} {% if t is mapping %}
  {{ t }}
{% elif t is not none and (t | string | trim) != '' and (t | float(-1)) >= 0 %}
  {% set ns = namespace(m={}) %}
  {% for e in resolved_entities %}
    {% set ns.m = dict(ns.m, **{e: t | float}) %}
  {% endfor %}
  {{ ns.m }}
{% else %}
  {{ {} }}
{% endif %}

variables.brightness_levels:
{% set ns = namespace(m={}) %} {% for e in phase_exclude_lights %}
  {% set ns.m = dict(ns.m, **{e: 0}) %}
{% endfor %} {{ dict(ns.m, **template_brightness_map) }}

variables.hands_off_entities:
{% set ns = namespace(items=[]) %} {% for entity_id, level in brightness_levels.items() %}
  {% if level is none or level is sameas false %}
    {% set ns.items = ns.items + [entity_id] %}
  {% endif %}
{% endfor %} {{ ns.items }}

