{% set m = {'Morning': morning_idle_brightness, 'Day': day_idle_brightness,
            'Evening': evening_idle_brightness, 'Night': night_idle_brightness} %}
{{ m.get(phase, 0) | int }}

variables.template_idle_map:
{% set t = template_idle_brightness %} {% if t is mapping %}
  {{ t }}
{% elif t is not none and (t | string | trim) != '' and (t | float(-1)) >= 0 %}
  {% set ns = namespace(m={}) %}
  {% for e in resolved_entities %}
    {% set ns.m = dict(ns.m, **{e: t | float}) %}
  {% endfor %}
  {{ ns.m }}
{% else %}
  {{ {} }}
{% endif %}

variables.idle_brightness:
{% set ns = namespace(m={}) %} {% if phase_idle_brightness %}
  {% for e in resolved_entities %}
    {% set ns.m = dict(ns.m, **{e: phase_idle_brightness}) %}
  {% endfor %}
{% endif %} {{ dict(ns.m, **template_idle_map) }}

variables.idle_entities:
{% set ns = namespace(items=[]) %} {% for e, level in idle_brightness.items() %}
  {% if level and e in resolved_entities and e not in hands_off_entities %}
    {% set ns.items = ns.items + [e] %}
  {% endif %}
{% endfor %} {{ ns.items }}

variables.idle_levels:
{% set ns = namespace(m={}) %} {% for e in idle_entities %}
  {% set ns.m = dict(ns.m, **{e: idle_brightness[e]}) %}
{% endfor %} {{ ns.m }}

variables.occupancy_clear_for_wait:
{% set ns = namespace(all_clear=true) %} {% for e in room_occupancy_entities %}
  {% if is_state(e, 'on') or
        (now() - states[e].last_changed).total_seconds() < (no_motion_wait | int) %}
    {% set ns.all_clear = false %}
  {% endif %}
{% endfor %} {{ ns.all_clear }}

variables.room_is_idle:
{{ idle_entities | length > 0
   and room_occupancy_entities | length > 0
   and occupancy_clear_for_wait }}

variables.allow_turn_on:
{{ manual_run
   or (trigger is defined and trigger.id is defined and trigger.id == 'motion_on')
   or occupied }}

variables.scope_entities:
{% set ns = namespace(entities=target_expanded_entities) %} {% for e in (target_named_entities | select('match', '^light\\.') | list) %}
  {% set did = device_id(e) %}
  {% set ns.entities = ns.entities + (device_entities(did) if did else [e]) %}
{% endfor %} {{ ns.entities | unique | list }}

variables.desired_scene:
{% set candidate = (scene_template | trim) %} {% if candidate and candidate is match('^[a-z0-9_]+\\.[a-z0-9_]+$') and states[candidate] is not none %}
  {{ candidate }}
{% elif phase_scene and states[phase_scene] is not none %}
  {{ phase_scene }}
{% else %}
  {{ '' }}
{% endif %}

variables.scene_covered_entities:
{% if desired_scene | length > 0 %}
  {{ state_attr(desired_scene, 'entity_id') | default([], true) | list }}
{% else %}
  {{ [] }}
{% endif %}

