  than waiting for the next one. "At least one reachable", not "none
  unavailable", so a dead entity can't block it; a bulb recovering
  beside reachable siblings waits for the tick. Can't use `trigger.*`,
  which isn't in scope here.
#} {% set ns = namespace(entities=[], devices=[], areas=[]) %} {% for key in ['entity_id', 'device_id', 'area_id', 'floor_id', 'label_id'] %}
  {% set v = room_target.get(key, []) %}
  {% set ids = [v] if v is string else v %}
  {% if key == 'entity_id' %}{% set ns.entities = ns.entities + ids %}
  {% elif key == 'device_id' %}{% set ns.devices = ns.devices + ids %}
  {% elif key == 'area_id' %}{% set ns.areas = ns.areas + ids %}
  {% elif key == 'floor_id' %}
    {% for f in ids %}{% set ns.areas = ns.areas + floor_areas(f) %}{% endfor %}
  {% else %}
    {% for l in ids %}
      {% set ns.entities = ns.entities + label_entities(l) %}
      {% set ns.devices = ns.devices + label_devices(l) %}
      {% set ns.areas = ns.areas + label_areas(l) %}
    {% endfor %}
  {% endif %}
{% endfor %} {% for d in ns.devices %}{% set ns.entities = ns.entities + device_entities(d) %}{% endfor %} {% for a in ns.areas %}{% set ns.entities = ns.entities + area_entities(a) %}{% endfor %} {% set light_entity_ids = ns.entities | select('match', '^light\\.')
     | reject('in', integration_entities('flare')) | unique | list %}
{{ light_entity_ids
   | reject('is_state', 'unavailable') | reject('is_state', 'unknown')
   | list | length > 0 }}

